import re
from typing import Literal

from app.schemas.classroom_schema import ClassroomResponse
from pydantic import BaseModel, ConfigDict, Field, field_validator

EnrollmentStatus = Literal[
    "active",
    "disabled",
    "removed",
]


# Class codes are generated by the backend from A-Z and 2-9 (see
# CLASS_CODE_ALPHABET in classroom_service). A code a student types must be
# plain ASCII letters and digits: no spaces, tabs or other whitespace, no
# punctuation and no look-alike Unicode characters. The same rule is checked
# in the browser (frontend/src/utils/validation.js, CLASS_CODE_PATTERN).
CLASS_CODE_PATTERN = r"^[A-Za-z0-9]{6,20}$"
CLASS_CODE_RE = re.compile(CLASS_CODE_PATTERN)


def normalize_class_code(value: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError("Class code cannot be empty.")

    if any(character.isspace() for character in value):
        raise ValueError("Class code cannot contain spaces or other whitespace.")

    if not CLASS_CODE_RE.fullmatch(value):
        raise ValueError(
            "Class code must be 6 to 20 letters (A-Z) and digits (0-9), "
            "with no special characters."
        )

    return value.upper()


class EnrollmentJoinRequest(BaseModel):
    class_code: str = Field(
        ...,
        description=(
            "Backend-generated class code supplied by the student: 6 to 20 "
            "ASCII letters and digits, with no whitespace or special characters."
        ),
        examples=["AB12CD34"],
        json_schema_extra={"pattern": CLASS_CODE_PATTERN, "minLength": 6, "maxLength": 20},
    )

    # Whitespace is refused, not trimmed: the code is checked exactly as sent.
    model_config = ConfigDict(
        extra="forbid",
    )

    @field_validator("class_code", mode="before")
    @classmethod
    def validate_class_code(
        cls,
        value: object,
    ) -> str:
        if not isinstance(value, str):
            raise ValueError("Class code must be text.")
        return normalize_class_code(value)


class EnrollmentStatusUpdate(BaseModel):
    status: EnrollmentStatus = Field(
        ...,
        description=(
            "Instructor-controlled enrollment status. "
            "`active` allows class participation, `disabled` temporarily "
            "blocks access, and `removed` indicates removal from the class."
        ),
    )

    model_config = ConfigDict(
        extra="forbid",
    )


class EnrollmentResponse(BaseModel):
    enrollment_id: int = Field(
        ...,
        gt=0,
        description="Unique enrollment identifier.",
    )
    class_id: int = Field(
        ...,
        gt=0,
        description="Enrolled classroom identifier.",
    )
    student_id: int = Field(
        ...,
        gt=0,
        description="Enrolled student identifier.",
    )
    status: EnrollmentStatus
    is_online: bool = False
    academic_integrity_score: float = 100.0

    model_config = ConfigDict(
        from_attributes=True,
        extra="forbid",
    )


class ClassMemberResponse(BaseModel):
    enrollment_id: int = Field(
        ...,
        gt=0,
    )
    student_id: int = Field(
        ...,
        gt=0,
    )
    school_id: str = Field(
        ...,
        min_length=10,
        max_length=10,
        pattern=r"^(\d{10}|\d{4}-\d{5})$",
    )
    name: str = Field(
        ...,
        min_length=1,
        max_length=120,
    )
    email: str = Field(
        ...,
        min_length=1,
        max_length=255,
    )
    status: EnrollmentStatus
    is_online: bool = False
    academic_integrity_score: float = 100.0

    model_config = ConfigDict(
        extra="forbid",
    )



class BulkEnrollmentRequest(BaseModel):
    emails: list[str] = Field(
        ...,
        min_length=1,
        max_length=500,
        description="List of student email addresses to bulk-enroll.",
    )

    model_config = ConfigDict(
        extra="forbid",
    )


class BulkEnrollmentResponse(BaseModel):
    enrolled: int = Field(..., description="Number of students successfully enrolled.")
    queued: int = Field(
        ...,
        description=(
            "Number of addresses with no account yet, saved as pending. "
            "They are enrolled when MIS creates a student account with the "
            "same university email, provided the classroom is still active."
        ),
    )
    invalid: int = Field(..., description="Number of invalid emails ignored.")
    already_enrolled: int = Field(
        default=0,
        description="Number of students who already had an enrollment record in this classroom.",
    )
    ineligible: int = Field(
        default=0,
        description=(
            "Number of addresses that belong to a faculty, admin or self-service "
            "guest account and were not enrolled."
        ),
    )
    suspended: int = Field(
        default=0,
        description=(
            "Number of students whose account MIS has suspended. They are not "
            "enrolled or queued; add them again once MIS reactivates them."
        ),
    )

    model_config = ConfigDict(
        extra="forbid",
    )


PendingEnrollmentSkipReason = Literal[
    "classroom_inactive",
    "enrollment_conflict",
    "audit_failed",
]


class PendingEnrollmentSkip(BaseModel):
    class_id: int
    reason: PendingEnrollmentSkipReason

    model_config = ConfigDict(
        extra="forbid",
    )


class PendingEnrollmentResult(BaseModel):
    """
    Outcome of applying a student's pending enrollments.

    Skipped rows stay pending so they can be retried; enrolled and
    already-enrolled rows are consumed.
    """

    enrolled_class_ids: list[int] = Field(default_factory=list)
    already_enrolled_class_ids: list[int] = Field(default_factory=list)
    skipped: list[PendingEnrollmentSkip] = Field(default_factory=list)

    model_config = ConfigDict(
        extra="forbid",
    )


class StudentClassroomResponse(BaseModel):
    enrollment_id: int = Field(
        ...,
        gt=0,
    )
    enrollment_status: EnrollmentStatus
    classroom: ClassroomResponse

    model_config = ConfigDict(
        extra="forbid",
    )


# SECURITY BOUNDARY:
# Students join classes using only a backend-generated class code.
# student_id comes from the authenticated access token.
# Clients cannot enroll another student or directly select a class_id.

# AUTHORIZATION BOUNDARY:
# Only the classroom owner may view members or change enrollment status.
# Students may view only their own classroom enrollments.

# STATUS BOUNDARY:
# Classroom availability uses Classroom.is_active.
# Enrollment membership uses active, disabled, or removed.
